import re
import os
import glob

# Let's look at the distinct patterns of JsonSerializer usage across all these files
all_cs_files = glob.glob('**/*.cs', recursive=True)
patterns = {}
for f in all_cs_files:
    if f in ['ArmClientOptions.cs', 'ArmEnvironment.cs']:
        continue
    with open(f) as fh:
        for i, line in enumerate(fh, 1):
            if 'JsonSerializer.' in line:
                stripped = line.strip()
                if f not in patterns:
                    patterns[f] = []
                patterns[f].append((i, stripped))

# Print unique patterns
unique_patterns = set()
for f, lines in patterns.items():
    for lineno, line in lines:
        unique_patterns.add(line)

print("Unique JsonSerializer patterns:")
for p in sorted(unique_patterns):
    print(f"  {p}")
EOF

